    function normalizeBool(raw) {
      if (typeof raw === 'boolean') return raw;
      if (typeof raw !== 'string') return false;
      return ['1', 'true', 'on', 'yes', 'y'].includes(raw.trim().toLowerCase());
    }

    function getBrowserCompatibilityState() {
      const userAgent = String(navigator.userAgent || '');
      const family = /Edg\//.test(userAgent)
        ? 'edge'
        : (/Firefox\//.test(userAgent)
          ? 'firefox'
          : (/Chrome\//.test(userAgent) ? 'chrome' : 'other'));
      const versionMatch = family === 'firefox'
        ? userAgent.match(/Firefox\/(\d+(?:\.\d+)?)/)
        : (family === 'edge'
          ? userAgent.match(/Edg\/(\d+(?:\.\d+)?)/)
          : userAgent.match(/Chrome\/(\d+(?:\.\d+)?)/));
      const elementPrototype = typeof Element === 'function' ? Element.prototype : null;
      return {
        family,
        version: versionMatch ? Number.parseFloat(versionMatch[1]) : 0,
        userAgent,
        platform: String(
          (navigator.userAgentData && navigator.userAgentData.platform)
          || navigator.platform
          || ''
        ),
        language: String(navigator.language || ''),
        protocol: window.location.protocol,
        secureContext: window.isSecureContext === true,
        pointerEvents: typeof window.PointerEvent === 'function',
        pointerCapture: !!(elementPrototype && elementPrototype.setPointerCapture),
        indexedDb: typeof window.indexedDB !== 'undefined',
        webAssembly: typeof window.WebAssembly === 'object',
        worker: typeof window.Worker === 'function',
        intersectionObserver: typeof window.IntersectionObserver === 'function',
        resizeObserver: typeof window.ResizeObserver === 'function',
        broadcastChannel: typeof window.BroadcastChannel === 'function',
        sendBeacon: typeof navigator.sendBeacon === 'function',
        clipboardText: !!(navigator.clipboard && navigator.clipboard.writeText),
        clipboardImage: !!(
          typeof window.ClipboardItem === 'function'
          && navigator.clipboard
          && navigator.clipboard.write
        ),
        dynamicViewportUnits: !!(
          window.CSS
          && typeof window.CSS.supports === 'function'
          && window.CSS.supports('height', '100dvh')
        ),
        overflowWrapAnywhere: !!(
          window.CSS
          && typeof window.CSS.supports === 'function'
          && window.CSS.supports('overflow-wrap', 'anywhere')
        ),
        contentVisibilityAuto: !!(
          window.CSS
          && typeof window.CSS.supports === 'function'
          && window.CSS.supports('content-visibility', 'auto')
        )
      };
    }

    function getEventTargetElement(event) {
      if (!event) return null;
      if (typeof event.composedPath === 'function') {
        const path = event.composedPath();
        for (let index = 0; index < path.length; index++) {
          if (path[index] instanceof Element) return path[index];
        }
      }
      return event.target instanceof Element ? event.target : null;
    }

    function initDebugMode() {
      try {
        const query = new URLSearchParams(window.location.search);
        const queryFlag = query.get(VWD_DEBUG_QUERY);
        const queryEnabled = normalizeBool(queryFlag);
        const localFlag = localStorage.getItem(VWD_DEBUG_FLAG_KEY);
        const localEnabled = normalizeBool(localFlag);
        if (queryFlag !== null) {
          vwdDebugEnabled = queryEnabled;
          localStorage.setItem(VWD_DEBUG_FLAG_KEY, vwdDebugEnabled ? '1' : '0');
        } else {
          vwdDebugEnabled = localEnabled;
        }
      } catch (_e) {
        vwdDebugEnabled = false;
      }
    }

    initDebugMode();

    function ensureDebugModeButton() {
      if (document.getElementById('btn-debug-mode')) return;
      const undoBtn = document.getElementById('btn-undo');
      const redoBtn = document.getElementById('btn-redo');
      if (!undoBtn || !redoBtn || !undoBtn.parentElement) return;
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.id = 'btn-debug-mode';
      btn.className = 'menu-btn debug-mode-btn';
      btn.setAttribute('title', 'Debug Mode Toggle');
      const label = document.createElement('span');
      label.id = 'debug-mode-label';
      label.textContent = 'Debug Mode: Off';
      btn.appendChild(label);
      undoBtn.parentElement.insertBefore(btn, redoBtn);
    }

